function putDeletionPreview(store:AtelierStore,token:string,ticket:CharacterDeleteTicket){const map=deletionPreviewMap(store),now=Date.now();for(const [key,value] of map)if(value.expiresAt<=now||value.workspaceInstanceId!==ticket.workspaceInstanceId)map.delete(key);while(map.size>=128)map.delete(map.keys().next().value!);map.set(token,ticket);}

